def solve():
	n = ipn()
	a = [ipl() for _ in range(n)]
	b = set([tuple(ipl()) for _ in range(ipn())])
	h = [(-sum((i[-1] for i in a)), tuple((i[0] for i in a)))]
	s = set()
	while h:
		(ss, tu) = heappop(h)
